css:
&.slide.tpl {
& { padding:62px 80px 70px; display:flex; flex-direction:column; gap:22px; }
header { flex:none; }
header p { color:var(--accent); font:20px var(--font-mono,var(--mono)); margin:0 0 12px; }
header h2 { font-size:60px; line-height:1.08; margin:0; max-width:46ch; text-wrap:balance; }
header :empty { display:none; }
header:has(h2:empty):has(p:empty) { display:none; }
.rib-stage { position:relative; flex:1; min-height:0; }
figure { position:absolute; inset:0; margin:0; display:grid; grid-template-rows:minmax(0,1fr) 100px; gap:18px; }
figure img { width:100%; height:100%; min-height:0; object-fit:contain; }
figcaption { display:flex; align-items:baseline; gap:28px; font-size:29px; line-height:1.3; height:100px; padding:0 8px; }
figcaption b { color:var(--accent); flex:none; max-width:450px; }
figcaption span { flex:1; }
.rib-base figcaption:has(span:empty) { display:none; }
.image-step { visibility:hidden; opacity:0!important; transition:opacity .2s ease; }
.image-step.in,.image-step:not([data-step]) { visibility:inherit; opacity:1!important; }
.image-step:has(~.image-step.in),.image-step:not([data-step]):has(~.image-step),.rib-base:has(~.image-step.in),.rib-base:has(~.image-step:not([data-step])) { visibility:hidden; opacity:0!important; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }

}
